def my_cad_function(args):
    import cadquery as cq
    import math

    shape = cq.importers.importStep(args["input_file"])   # ALWAYS load the input
    base = shape.val() if hasattr(shape, "val") else shape

    # --- helpers ---
    def bb_str(bb):
        return f"([{bb.xmin:.3f},{bb.ymin:.3f},{bb.zmin:.3f}]..[{bb.xmax:.3f},{bb.ymax:.3f},{bb.zmax:.3f}])"

    def v3(v):
        return [round(v.x, 3), round(v.y, 3), round(v.z, 3)]

    def dir_parallel_y(d, tol=1e-3):
        # d can be cq.Vector or gp_Dir-like
        try:
            dx, dy, dz = float(d.x), float(d.y), float(d.z)
        except Exception:
            dx, dy, dz = float(d.X()), float(d.Y()), float(d.Z())
        # parallel to +/-Y
        return abs(abs(dy) - 1.0) < tol and abs(dx) < tol and abs(dz) < tol

    def circle_geom_center(edge):
        """True circle center for a CIRCLE edge, including partial arcs."""
        from OCP.BRepAdaptor import BRepAdaptor_Curve
        from OCP.GeomAbs import GeomAbs_Circle
        c = BRepAdaptor_Curve(edge.wrapped)
        if c.GetType() != GeomAbs_Circle:
            return None
        circ = c.Circle()
        p = circ.Location()
        return cq.Vector(p.X(), p.Y(), p.Z())

    def cyl_axis_xz(face):
        from OCP.BRepAdaptor import BRepAdaptor_Surface
        from OCP.GeomAbs import GeomAbs_Cylinder
        s = BRepAdaptor_Surface(face.wrapped)
        if s.GetType() != GeomAbs_Cylinder:
            return None
        cyl = s.Cylinder()
        ax = cyl.Axis()
        d = ax.Direction()
        if not dir_parallel_y(d, tol=2e-3):
            return None
        p = ax.Location()
        return float(p.X()), float(p.Z()), float(cyl.Radius())

    def uniq_pts_xz(pts, tol=0.25):
        out = []
        for (x, z) in pts:
            found = False
            for (xx, zz) in out:
                if math.hypot(x - xx, z - zz) <= tol:
                    found = True
                    break
            if not found:
                out.append((x, z))
        return out

    def probe_perimeter_inside(solid, x, z, y_outer, y_inner, r=2.5, y_off=0.25, n=12):
        """Return (ok, n_fail_outer, n_fail_inner). ok=True means all samples are inside solid."""
        fails_outer = 0
        fails_inner = 0
        for i in range(n):
            ang = (2.0 * math.pi) * (i / n)
            px = x + (r - 0.05) * math.cos(ang)
            pz = z + (r - 0.05) * math.sin(ang)
            # sample slightly inside each face
            p_outer = cq.Vector(px, y_outer - y_off, pz)
            p_inner = cq.Vector(px, y_inner + y_off, pz)
            try:
                if not solid.isInside(p_outer, 1e-6):
                    fails_outer += 1
                if not solid.isInside(p_inner, 1e-6):
                    fails_inner += 1
            except Exception:
                # If isInside isn't available in this build, be conservative and treat as failure
                return (False, n, n)
        return (fails_outer == 0 and fails_inner == 0, fails_outer, fails_inner)

    def build_cyl_tool(points_xz, y_min, y_max, r, margin=3.0):
        h = (y_max - y_min) + 2.0 * margin
        y0 = y_min - margin
        cyls = []
        for (x, z) in points_xz:
            cyls.append(cq.Solid.makeCylinder(r, h, cq.Vector(x, y0, z), cq.Vector(0, 1, 0)))
        return cq.Compound.makeCompound(cyls) if cyls else None

    def mouth_coverage_ratio(solid, x, z, y_plane, r=2.5, tol_xyz=0.6):
        """Sum arc-length coverage of all r circle edges at a given plane near (x,z)."""
        target = cq.Vector(x, y_plane, z)
        total_len = 0.0
        for e in solid.Edges():
            try:
                if e.geomType() != "CIRCLE":
                    continue
                if abs(e.radius() - r) > 0.08:
                    continue
                c = circle_geom_center(e)
                if c is None:
                    continue
                if abs(c.y - y_plane) > tol_xyz:
                    continue
                if math.hypot(c.x - x, c.z - z) > tol_xyz:
                    continue
                total_len += float(e.Length())
            except Exception:
                continue
        full = 2.0 * math.pi * r
        return total_len / full if full > 0 else 0.0

    # --- targets from prompt ---
    x_list = [-34.757, -9.7685, 22.7315]
    z_list = [-10.746, 0.504, 11.754]
    z_center = 0.504

    print("TARGETS:")
    print(f"  x_list={x_list}")
    print(f"  z_list={z_list}")
    print(f"  shift rule: +/-5mm in Z toward z_center={z_center}")

    solids = list(base.Solids())
    print(f"Imported solids: {len(solids)}")
    if len(solids) < 6:
        print("ERROR: Expected at least 6 solids to access #4 and #5")
        return shape

    # Platforms are specified as solids #4 and #5
    platforms = [(4, solids[4]), (5, solids[5])]

    new_solids = solids[:]

    for (si, s) in platforms:
        bb = s.BoundingBox()
        y_min, y_max = bb.ymin, bb.ymax
        y_mid = 0.5 * (y_min + y_max)
        print("\n--- PLATFORM ---")
        print(f"Solid#{si} bbox={bb_str(bb)}")
        print(f"  y_inner=y_min={y_min:.3f}, y_outer=y_max={y_max:.3f}, y_mid={y_mid:.3f}")

        # 1) Find existing r=2.5 cylindrical faces (Y-axis) near the 3x3 grid (incl. +/-5 Z variants)
        candidate_axes = []
        for f in s.Faces():
            try:
                if f.geomType() != "CYLINDER":
                    continue
                ax = cyl_axis_xz(f)
                if ax is None:
                    continue
                x_ax, z_ax, r_ax = ax
                if abs(r_ax - 2.5) > 0.08:
                    continue

                # near any of our grid (allow +/-5 Z from each z target)
                near_x = min(abs(x_ax - xt) for xt in x_list) < 1.5
                if not near_x:
                    continue
                near_z = False
                for zt in z_list:
                    if abs(z_ax - zt) < 1.5:
                        near_z = True
                    if abs(z_ax - (zt + (5.0 if zt < z_center else (-5.0 if zt > z_center else 0.0)))) < 1.5:
                        near_z = True
                if not near_z:
                    continue

                candidate_axes.append((x_ax, z_ax))
            except Exception:
                continue

        candidate_axes = uniq_pts_xz(candidate_axes, tol=0.35)
        print(f"  Detected existing Y-axis r~2.5 hole axes near grid: {len(candidate_axes)}")
        for (x_ax, z_ax) in sorted(candidate_axes):
            print(f"    axis approx at (x,z)=({x_ax:.3f},{z_ax:.3f})")

        # 2) Plug those existing pattern holes (so we can rebuild cleanly)
        plug_r = 2.55
        plugs = build_cyl_tool(candidate_axes, y_min, y_max, plug_r, margin=3.0)
        if plugs is None:
            print("  WARNING: no plugs created (could not detect existing pattern holes); proceeding to cut anyway")
            s_filled = s
        else:
            try:
                s_filled = s.union(plugs)
                added = s_filled.cut(s)
                print(f"  Plug added volume={added.Volume():.3f} mm^3  added_bbox={bb_str(added.BoundingBox())}")
            except Exception as ex:
                print(f"  WARNING: plug union failed: {ex}; proceeding without fill")
                s_filled = s

        # 3) Decide final hole centers using perimeter-in-solid probing; shift by +/-5 in Z toward z_center if needed
        final_pts = []
        shifts = 0
        for x in x_list:
            for z0 in z_list:
                ok0, fo0, fi0 = probe_perimeter_inside(s_filled, x, z0, y_max, y_min, r=2.5)
                z_use = z0
                if not ok0:
                    # primary mandated shift direction toward z_center
                    if abs(z0 - z_center) < 1e-6:
                        # center row: try +5 then -5 (still toward center is undefined)
                        z_cand = [z0 + 5.0, z0 - 5.0]
                    else:
                        dz = -5.0 if z0 > z_center else 5.0
                        z_cand = [z0 + dz]
                    picked = False
                    for z1 in z_cand:
                        ok1, fo1, fi1 = probe_perimeter_inside(s_filled, x, z1, y_max, y_min, r=2.5)
                        if ok1:
                            z_use = z1
                            shifts += 1
                            picked = True
                            print(f"  shift: (x,z)=({x:.3f},{z0:.3f}) -> z={z_use:.3f}  (probe failed outer/inner={fo0}/{fi0})")
                            break
                    if not picked:
                        # keep original but log it; will still cut (best effort)
                        print(f"  WARNING: probe failed and shift did not resolve for (x,z)=({x:.3f},{z0:.3f}); keeping z={z0:.3f}  (probe failed outer/inner={fo0}/{fi0})")
                final_pts.append((x, z_use))

        print(f"  Final hole points: {len(final_pts)} (shifted={shifts})")
        for (x, z) in final_pts:
            print(f"    (x,y_mid,z)=({x:.3f},{y_mid:.3f},{z:.3f})")

        # 4) Re-cut clean through holes
        cut_tool = build_cyl_tool(final_pts, y_min, y_max, 2.5, margin=3.0)
        if cut_tool is None:
            print("  ERROR: no cut tool created")
            s_new = s
        else:
            s_new = s_filled.cut(cut_tool)

        # 5) QA checks
        try:
            removed = s_filled.cut(s_new)
            bbrem = removed.BoundingBox()
            print(f"  Removed volume (platform#{si})={removed.Volume():.3f} mm^3  removed_bbox={bb_str(bbrem)}")
            print(f"  Removed y_range=[{bbrem.ymin:.3f},{bbrem.ymax:.3f}] vs platform [{y_min:.3f},{y_max:.3f}]")
        except Exception as ex:
            print(f"  WARNING: could not compute removed volume for platform#{si}: {ex}")

        # Verify full circular mouths at both planes for each intended hole
        print("  Mouth coverage check (sum arc length / full circumference) at y_min and y_max:")
        for (x, z) in final_pts:
            cov_out = mouth_coverage_ratio(s_new, x, z, y_max, r=2.5)
            cov_in = mouth_coverage_ratio(s_new, x, z, y_min, r=2.5)
            print(f"    (x,z)=({x:.3f},{z:.3f})  cov@y_max={cov_out:.3f}  cov@y_min={cov_in:.3f}")

        new_solids[si] = s_new

    out = cq.Compound.makeCompound(new_solids)

    # global removed vs incoming
    try:
        removed_total = base.cut(out)
        bb = removed_total.BoundingBox()
        print("\nTOTAL REMOVED (base - out):")
        print(f"  volume={removed_total.Volume():.3f} mm^3")
        print(f"  bbox={bb_str(bb)}")
        print(f"  center={v3(removed_total.Center())}")
    except Exception as ex:
        print(f"WARNING: could not compute total removed: {ex}")

    return out

def my_cad_function(args):
    import cadquery as cq

    shape = cq.importers.importStep(args["input_file"])   # ALWAYS load the input
    base = shape.val() if hasattr(shape, "val") else shape

    # --- numbers explicitly named by sub-goal ---
    y_front = 3.175
    edge_idx_target = 0
    face_idx_front = 496
    face_idx_cyl = 2
    r_edge_named = 15.25
    r_cyl_named = 15.75
    chamfer_size = 1.0

    print("TARGET NUMBERS:")
    print(f"  y_front={y_front}")
    print(f"  edge_idx_target={edge_idx_target} (named r={r_edge_named})")
    print(f"  face_idx_front={face_idx_front} (front plane)")
    print(f"  face_idx_cyl={face_idx_cyl} (central cylindrical)")
    print(f"  r_cyl_named={r_cyl_named}")
    print(f"  chamfer_size={chamfer_size}")

    # --- resolve indexed entities and verify against the provided geometry index ---
    all_edges = base.Edges()
    all_faces = base.Faces()
    print(f"Entity counts: faces={len(all_faces)} edges={len(all_edges)} solids={len(base.Solids())}")

    if edge_idx_target >= len(all_edges) or face_idx_front >= len(all_faces) or face_idx_cyl >= len(all_faces):
        print("ERROR: Provided indices exceed entity counts; returning original shape")
        return shape

    edge0 = all_edges[edge_idx_target]
    f_front = all_faces[face_idx_front]
    f_cyl = all_faces[face_idx_cyl]

    def pnt_tuple(v):
        t = v.toTuple() if hasattr(v, "toTuple") else tuple(v)
        return (float(t[0]), float(t[1]), float(t[2]))

    def circle_data(e):
        try:
            if hasattr(e, "geomType") and e.geomType() != "CIRCLE":
                return None
            c = e.Center()
            r = e.radius()
            cx, cy, cz = pnt_tuple(c)
            return (cx, cy, cz, float(r))
        except Exception:
            return None

    e0_cd = circle_data(edge0)
    print("Resolved entities (index-check):")
    print(f"  face#{face_idx_front}: area={f_front.Area():.3f} center={tuple(round(x,6) for x in pnt_tuple(f_front.Center()))}")
    try:
        n = f_front.normalAt()
        print(f"    normal={tuple(round(x,6) for x in pnt_tuple(n))}")
    except Exception as ex:
        print("    normalAt failed:", ex)

    print(f"  face#{face_idx_cyl}: area={f_cyl.Area():.3f} center={tuple(round(x,6) for x in pnt_tuple(f_cyl.Center()))}")
    try:
        # Face radius helper sometimes exists for cylinders
        if hasattr(f_cyl, "radius"):
            print(f"    face.radius()={f_cyl.radius():.6f}")
    except Exception as ex:
        print("    face.radius() failed:", ex)

    if e0_cd:
        cx, cy, cz, r0 = e0_cd
        print(f"  edge#{edge_idx_target}: CIRCLE center={tuple(round(x,6) for x in (cx,cy,cz))} r={r0:.6f}")
        print(f"    delta_y_to_front={cy - y_front:.6f}")
    else:
        print(f"  edge#{edge_idx_target}: not detected as circle via cq Edge API (continuing anyway)")

    # --- find which solid contains the target edge (compound has 2 solids) ---
    solids = list(base.Solids())
    target_solid = None
    edge0_h = None
    try:
        edge0_h = edge0.hashCode()
    except Exception:
        try:
            edge0_h = edge0.wrapped.HashCode(2147483647)
        except Exception:
            edge0_h = None

    for si, s in enumerate(solids):
        found = False
        for e in s.Edges():
            try:
                eh = e.hashCode()
            except Exception:
                try:
                    eh = e.wrapped.HashCode(2147483647)
                except Exception:
                    continue
            if edge0_h is not None and eh == edge0_h:
                found = True
                break
        if found:
            target_solid = s
            print(f"Target edge belongs to solid index #{si} (of {len(solids)})")
            break

    if target_solid is None:
        # Fallback: pick the solid whose bbox includes the edge center
        print("WARNING: Could not locate solid by edge hash; falling back to nearest solid by edge center")
        if e0_cd:
            pt = cq.Vector(e0_cd[0], e0_cd[1], e0_cd[2])
            best = None
            for si, s in enumerate(solids):
                bb = s.BoundingBox()
                cx_bb = 0.5 * (bb.xmin + bb.xmax)
                cy_bb = 0.5 * (bb.ymin + bb.ymax)
                cz_bb = 0.5 * (bb.zmin + bb.zmax)
                d2 = (cx_bb - pt.x) ** 2 + (cy_bb - pt.y) ** 2 + (cz_bb - pt.z) ** 2
                if best is None or d2 < best[0]:
                    best = (d2, si, s)
            if best:
                target_solid = best[2]
                print(f"Fallback chose solid #{best[1]} by bbox-center distance")

    if target_solid is None:
        print("ERROR: No target solid found; returning original")
        return shape

    other_solids = [s for s in solids if not s.wrapped.IsSame(target_solid.wrapped)]

    # --- determine fillet height by finding the nearby r~15.75 circle edge just below the front plane ---
    # The index hints one such edge is at y=2.675 for r=15.75 (0.5mm below y_front).
    best_y = None
    best_info = None
    for e in target_solid.Edges():
        cd = circle_data(e)
        if not cd:
            continue
        cx, cy, cz, r = cd
        if abs(cx) > 0.2 or abs(cz) > 0.2:
            continue
        if abs(r - r_cyl_named) > 0.2:
            continue
        if cy >= y_front - 1e-6:
            continue
        # prefer the one closest to the front plane
        d = abs((y_front - 0.5) - cy)
        if best_info is None or d < best_info[0]:
            best_info = (d, e, cd)
            best_y = cy

    if best_y is None:
        fill_depth = 0.55  # safe default around the expected 0.5mm fillet
        print("WARNING: Could not find the cyl/fillet circle edge below front; using default fill_depth=0.55")
    else:
        fill_depth = (y_front - best_y) + 0.02  # small epsilon to ensure full cover
        print("Found likely cyl/fillet junction circle below front:")
        _, e_b, (cx, cy, cz, r) = best_info
        print(f"  center={tuple(round(x,6) for x in (cx,cy,cz))} r={r:.6f} y={cy:.6f}")
        print(f"  computed fill_depth=(y_front - y_edge)+0.02 = {fill_depth:.6f}")

    # --- heal to a sharp edge by unioning an annular ring that restores the missing corner volume ---
    # Use the NAMED radii: inner=15.25 (edge_idx 0), outer=15.75 (cyl face #2)
    r_inner = r_edge_named
    r_outer = r_cyl_named

    if not (r_outer > r_inner):
        print("ERROR: r_outer not greater than r_inner; cannot build annular heal ring. Returning original")
        return shape

    wp_front = cq.Workplane(cq.Plane(origin=(0, y_front, 0), normal=(0, 1, 0), xDir=(1, 0, 0)))
    heal_ring = wp_front.circle(r_outer).circle(r_inner).extrude(-fill_depth).val()

    healed = target_solid.fuse(heal_ring)

    # --- find the NEW sharp rim edge at the front plane (y=3.175) and radius ~15.75 ---
    rim_candidates = []
    for e in healed.Edges():
        cd = circle_data(e)
        if not cd:
            continue
        cx, cy, cz, r = cd
        if abs(cx) > 0.2 or abs(cz) > 0.2:
            continue
        if abs(cy - y_front) > 0.05:
            continue
        if abs(r - r_outer) > 0.2:
            continue
        rim_candidates.append((abs(r - r_outer) + abs(cy - y_front), e, cd))

    print(f"Rim candidates on healed solid near front: {len(rim_candidates)}")
    rim_edge = None
    if rim_candidates:
        rim_candidates.sort(key=lambda t: t[0])
        _, rim_edge, (cx, cy, cz, r) = rim_candidates[0]
        print("Selected front rim edge for chamfer:")
        print(f"  center={tuple(round(x,6) for x in (cx,cy,cz))} r={r:.6f} delta_y={cy - y_front:.6f}")
    else:
        print("WARNING: No suitable front rim edge found; returning healed-without-chamfer")

    # --- Apply 1.0 mm chamfer on that rim edge only ---
    chamfered = healed
    if rim_edge is not None:
        try:
            rim_h = rim_edge.hashCode()
        except Exception:
            try:
                rim_h = rim_edge.wrapped.HashCode(2147483647)
            except Exception:
                rim_h = None

        class _SameHashEdgeSelector(cq.selectors.Selector):
            def __init__(self, h):
                self._h = h
            def filter(self, objectList):
                out = []
                for o in objectList:
                    try:
                        oh = o.hashCode()
                    except Exception:
                        try:
                            oh = o.wrapped.HashCode(2147483647)
                        except Exception:
                            continue
                    if self._h is not None and oh == self._h:
                        out.append(o)
                return out

        try:
            wp = cq.Workplane().newObject([healed])
            wp2 = wp.edges(_SameHashEdgeSelector(rim_h)).chamfer(chamfer_size)
            chamfered = wp2.val()
            print("Chamfer applied on selected front rim edge.")
        except Exception as ex:
            print("WARNING: Chamfer failed; returning healed solid without chamfer:", ex)
            chamfered = healed

    # --- Reassemble compound with other solids unchanged ---
    if other_solids:
        result = cq.Compound.makeCompound([chamfered] + other_solids)
    else:
        result = chamfered

    # --- Placement self-check (added material and removed material) ---
    try:
        removed = target_solid.cut(chamfered)
        added = chamfered.cut(target_solid)
        print("SELF-CHECK (edited solid diff):")
        print(f"  removed.Volume={removed.Volume():.6f}  added.Volume={added.Volume():.6f}")
        if added.Volume() > 1e-6:
            ac = pnt_tuple(added.Center())
            bb = added.BoundingBox()
            print(f"  added.Center={tuple(round(x,6) for x in ac)}")
            print(f"  added.BBox=(xmin={bb.xmin:.6f}, ymin={bb.ymin:.6f}, zmin={bb.zmin:.6f}, xmax={bb.xmax:.6f}, ymax={bb.ymax:.6f}, zmax={bb.zmax:.6f})")
            print(f"  added delta_y_to_front = {ac[1] - y_front:.6f} mm")
        if removed.Volume() > 1e-6:
            rc = pnt_tuple(removed.Center())
            bb = removed.BoundingBox()
            print(f"  removed.Center={tuple(round(x,6) for x in rc)}")
            print(f"  removed.BBox=(xmin={bb.xmin:.6f}, ymin={bb.ymin:.6f}, zmin={bb.zmin:.6f}, xmax={bb.xmax:.6f}, ymax={bb.ymax:.6f}, zmax={bb.zmax:.6f})")
            print(f"  removed delta_y_to_front = {rc[1] - y_front:.6f} mm")
    except Exception as ex:
        print("WARNING: self-check boolean diff failed:", ex)

    return result

def my_cad_function(args):
    import cadquery as cq
    from cadquery import selectors as sel

    shape = cq.importers.importStep(args["input_file"])   # ALWAYS load the input
    base = shape.val() if hasattr(shape, "val") else shape

    # ----------------------------
    # Helpers
    # ----------------------------
    def _key(e):
        try:
            return e.hashCode()
        except Exception:
            return id(e)

    def _vtu(v):
        try:
            return (float(v.x), float(v.y), float(v.z))
        except Exception:
            try:
                return v.toTuple()
            except Exception:
                return tuple(v)

    print("Base: solids=", len(base.Solids()), "faces=", len(base.Faces()), "edges=", len(base.Edges()))

    # ----------------------------
    # Resolve targets by index (from provided geometry index)
    # ----------------------------
    faces = base.Faces()
    edges = base.Edges()

    target_face_idx = 1
    seed_edge_idx = [25, 26, 27, 29]
    fillet_r = 2.0

    if target_face_idx >= len(faces):
        print("ERROR: target_face_idx out of range:", target_face_idx, "/", len(faces))
        # do something minimal (but not a no-op): attempt fillet on the two r=7.032 edges by nearest point
        out = base
        for ei in [26, 27]:
            if ei < len(edges):
                pt = _vtu(edges[ei].Center())
                try:
                    out = cq.Workplane(obj=out).edges(sel.NearestToPointSelector(pt)).fillet(fillet_r).val()
                    print("Fallback fillet succeeded on edge idx", ei)
                except Exception as e:
                    print("Fallback fillet failed on edge idx", ei, "err=", repr(e))
        return out

    target_face = faces[target_face_idx]
    print("Resolved target face #1:")
    try:
        print("  area=", float(target_face.Area()), "center=", _vtu(target_face.Center()))
    except Exception as e:
        print("  could not print area/center:", repr(e))
    try:
        n = target_face.normalAt()  # IMPORTANT: no (u,v) args
        print("  normalAt()=", _vtu(n))
    except Exception as e:
        print("  could not print normalAt():", repr(e))

    seed_edges = []
    for i in seed_edge_idx:
        if i < len(edges):
            seed_edges.append(edges[i])
    print("Seed edges resolved:", [(i, edges[i].geomType() if i < len(edges) else None) for i in seed_edge_idx])
    for i in seed_edge_idx:
        if i < len(edges):
            e = edges[i]
            try:
                print(f"  seed edge_idx={i} type={e.geomType()} len={e.Length():.3f} center={_vtu(e.Center())}")
            except Exception as ex:
                print("  seed edge print failed for", i, repr(ex))

    if not seed_edges:
        print("ERROR: No seed edges resolved; attempting broad nearest-point fillet near expected slot center.")
        # center from index for r=7.032 arcs: [27.325, 22.101, 51.269]
        guess_pt = (27.325, 22.101, 51.269)
        try:
            return cq.Workplane(obj=base).edges(sel.NearestToPointSelector(guess_pt)).fillet(fillet_r).val()
        except Exception as e:
            print("Broad nearest-point fillet failed:", repr(e))
            return base

    seed_keys = set(_key(e) for e in seed_edges)

    # ----------------------------
    # Identify which solid owns the seed edges (by hash match count)
    # ----------------------------
    solids = list(base.Solids())
    best_si = 0
    best_match = -1
    for si, s in enumerate(solids):
        try:
            skeys = set(_key(e) for e in s.Edges())
            match = len(seed_keys.intersection(skeys))
        except Exception as e:
            print("  could not score solid", si, "err=", repr(e))
            match = 0
        print(f"Solid[{si}] seed-edge match count={match}")
        if match > best_match:
            best_match = match
            best_si = si

    target_solid = solids[best_si]
    print("Chosen target solid idx=", best_si, "match_count=", best_match, "vol=", float(target_solid.Volume()))

    # ----------------------------
    # Find the perimeter loop wire on face #1 that contains the seed edges
    # ----------------------------
    wires = list(target_face.Wires())
    print("Target face wires:", len(wires))
    best_wire = None
    best_wscore = -1
    best_wire_edges = []

    for wi, w in enumerate(wires):
        w_edges = list(w.Edges())
        w_keys = set(_key(we) for we in w_edges)
        score = len(seed_keys.intersection(w_keys))
        print(f"  Wire[{wi}] edge_count={len(w_edges)} seed_match_count={score}")
        if score > best_wscore:
            best_wscore = score
            best_wire = w
            best_wire_edges = w_edges

    if best_wire is None or best_wscore <= 0:
        print("WARNING: No wire on face #1 matched seed edges. Falling back to filleting only the seed edges.")
        best_wire_edges = seed_edges

    # Deduplicate loop edges
    uniq = {}
    for e in best_wire_edges:
        uniq[_key(e)] = e
    loop_edges = list(uniq.values())

    print("Perimeter/target edge set selected:", len(loop_edges), "(wire_score=", best_wscore, ")")
    for k, e in enumerate(loop_edges[:30]):
        try:
            print(f"  LoopEdge[{k}] type={e.geomType()} len={e.Length():.3f} center={_vtu(e.Center())}")
        except Exception as ex:
            print("  LoopEdge print failed:", repr(ex))

    # ----------------------------
    # Apply fillet on the chosen solid, then recombine with the other solid (wheel)
    # ----------------------------
    bb_before = target_solid.BoundingBox()
    vol_before = float(target_solid.Volume())
    print("Target solid bbox BEFORE:", (bb_before.xmin, bb_before.ymin, bb_before.zmin), "..", (bb_before.xmax, bb_before.ymax, bb_before.zmax))
    print("Target solid vol  BEFORE:", vol_before)

    filleted_solid = None
    try:
        filleted_solid = cq.Workplane(obj=target_solid).newObject(loop_edges).fillet(fillet_r).val()
        print("One-shot fillet succeeded on selected edge set.")
    except Exception as e:
        print("One-shot fillet FAILED; attempting sequential per-edge fillets. Error:", repr(e))
        filleted_solid = target_solid
        applied = 0
        for j, oe in enumerate(loop_edges):
            pt = _vtu(oe.Center())
            try:
                filleted_solid = cq.Workplane(obj=filleted_solid).edges(sel.NearestToPointSelector(pt)).fillet(fillet_r).val()
                applied += 1
                print(f"  Sequential fillet ok for edge#{j} near point {pt}")
            except Exception as e2:
                print(f"  Sequential fillet FAILED for edge#{j} near point {pt}. Error:", repr(e2))
        print("Sequential applied count:", applied, "/", len(loop_edges))

        # If literally nothing applied, try at least one seed-edge nearest point
        if applied == 0 and seed_edges:
            pt = _vtu(seed_edges[0].Center())
            try:
                filleted_solid = cq.Workplane(obj=filleted_solid).edges(sel.NearestToPointSelector(pt)).fillet(fillet_r).val()
                print("Last-resort: filleted one seed edge near", pt)
            except Exception as e3:
                print("Last-resort single-edge fillet also failed:", repr(e3))

    bb_after = filleted_solid.BoundingBox()
    vol_after = float(filleted_solid.Volume())
    print("Target solid bbox AFTER :", (bb_after.xmin, bb_after.ymin, bb_after.zmin), "..", (bb_after.xmax, bb_after.ymax, bb_after.zmax))
    print("Target solid vol  AFTER :", vol_after)
    print("Target solid vol  delta :", vol_after - vol_before)

    # Difference self-check (material removed by fillet)
    try:
        removed = target_solid.cut(filleted_solid)
        bb_removed = removed.BoundingBox()
        print("Removed (before - after) center:", _vtu(removed.Center()))
        print("Removed bbox:", (bb_removed.xmin, bb_removed.ymin, bb_removed.zmin), "..", (bb_removed.xmax, bb_removed.ymax, bb_removed.zmax))
    except Exception as e:
        print("Could not compute removed region for self-check:", repr(e))

    other_solids = [s for si, s in enumerate(solids) if si != best_si]
    if other_solids:
        out = cq.Compound.makeCompound([filleted_solid] + other_solids)
        print("Returned a Compound with solids:", 1 + len(other_solids))
    else:
        out = filleted_solid
        print("Returned single filleted solid.")

    bb_base = base.BoundingBox()
    bb_out = out.BoundingBox()
    print("Global bbox BEFORE:", (bb_base.xmin, bb_base.ymin, bb_base.zmin), "..", (bb_base.xmax, bb_base.ymax, bb_base.zmax))
    print("Global bbox AFTER :", (bb_out.xmin, bb_out.ymin, bb_out.zmin), "..", (bb_out.xmax, bb_out.ymax, bb_out.zmax))
    print("Global bbox delta :",
          (bb_out.xmin - bb_base.xmin, bb_out.ymin - bb_base.ymin, bb_out.zmin - bb_base.zmin), "..",
          (bb_out.xmax - bb_base.xmax, bb_out.ymax - bb_base.ymax, bb_out.zmax - bb_base.zmax))

    return out

def my_cad_function(args):
    import cadquery as cq

    shape = cq.importers.importStep(args["input_file"])   # ALWAYS load the input
    base = shape.val() if hasattr(shape, "val") else shape

    solids = base.Solids()
    print(f"SELECTED: {len(solids)} solids from imported STEP")
    for i, s in enumerate(solids):
        bb = s.BoundingBox()
        try:
            v = s.Volume()
        except Exception:
            v = float('nan')
        print(
            f"  solid s{i}: vol={v:.3f}  bbox=({bb.xmin:.3f},{bb.ymin:.3f},{bb.zmin:.3f})..({bb.xmax:.3f},{bb.ymax:.3f},{bb.zmax:.3f})  lens=({bb.xlen:.3f},{bb.ylen:.3f},{bb.zlen:.3f})"
        )

    if len(solids) < 1:
        print("ERROR: No solids found; returning input")
        return shape

    # --- Choose the newly created blade (copy) heuristically: most 'diagonal' blade has largest X span ---
    blade_cands = []
    for i, s in enumerate(solids):
        bb = s.BoundingBox()
        # hub is small (~50mm); blades are hundreds of mm
        if max(bb.xlen, bb.zlen) > 150 and abs(bb.ylen - 12.7) < 2.0:
            blade_cands.append(i)
    print(f"SELECTED: {len(blade_cands)} candidate blade solids (max(xlen,zlen)>150 and ylen~12.7) idx={blade_cands}")

    if not blade_cands:
        print("ERROR: Could not identify any blade solids; returning input")
        return shape

    copy_idx = max(blade_cands, key=lambda k: solids[k].BoundingBox().xlen)
    target = solids[copy_idx]
    bb_t = target.BoundingBox()
    print(
        f"USING: solid s{copy_idx} as target newly-copied blade for long-edge fillets  "
        f"bbox=({bb_t.xmin:.3f},{bb_t.ymin:.3f},{bb_t.zmin:.3f})..({bb_t.xmax:.3f},{bb_t.ymax:.3f},{bb_t.zmax:.3f})  "
        f"lens=({bb_t.xlen:.3f},{bb_t.ylen:.3f},{bb_t.zlen:.3f})"
    )

    # Helpers
    def hc(sh):
        try:
            return sh.hashCode()
        except Exception:
            try:
                return sh.wrapped.HashCode(2147483647)
            except Exception:
                return id(sh)

    def vsub(a, b):
        return cq.Vector(a.x - b.x, a.y - b.y, a.z - b.z)

    def vadd(a, b):
        return cq.Vector(a.x + b.x, a.y + b.y, a.z + b.z)

    def vscale(a, s):
        return cq.Vector(a.x * s, a.y * s, a.z * s)

    def vdot(a, b):
        return a.x * b.x + a.y * b.y + a.z * b.z

    def vlen(a):
        return a.Length

    def vnorm(a):
        L = a.Length
        if L < 1e-9:
            return cq.Vector(0, 0, 1)
        return cq.Vector(a.x / L, a.y / L, a.z / L)

    def dist_point_to_axis(pt, origin, axis_dir):
        v = vsub(pt, origin)
        t = vdot(v, axis_dir)
        proj = vscale(axis_dir, t)
        perp = vsub(v, proj)
        return perp.Length, t

    # --- Determine blade axis from two end faces (small planar faces) ---
    t_faces = target.Faces()
    end_face_cands = []
    for fi, f in enumerate(t_faces):
        if f.geomType() != "PLANE":
            continue
        a = f.Area()
        # end faces in the provided index are ~256 mm^2; accept a band
        if 150.0 <= a <= 400.0:
            c = f.Center()
            end_face_cands.append((fi, a, c, f))

    print(f"SELECTED: {len(end_face_cands)} planar end-face candidates on s{copy_idx} (area 150..400)")
    for k, (fi, a, c, _) in enumerate(end_face_cands[:10]):
        print(f"  end_face_cand[{k}]: local_face_idx={fi} area={a:.3f} center=[{c.x:.3f},{c.y:.3f},{c.z:.3f}]")

    axis_origin = target.Center()
    axis_dir = cq.Vector(0, 0, 1)

    if len(end_face_cands) >= 2:
        # pick the farthest pair by center distance
        best = None
        for i in range(len(end_face_cands)):
            for j in range(i + 1, len(end_face_cands)):
                ci = end_face_cands[i][2]
                cj = end_face_cands[j][2]
                d = vsub(cj, ci).Length
                if best is None or d > best[0]:
                    best = (d, ci, cj)
        L, c1, c2 = best
        axis_origin = vscale(vadd(c1, c2), 0.5)
        axis_dir = vnorm(vsub(c2, c1))
        print(
            "AXIS: derived from farthest end-face centers  "
            f"L~{L:.3f}  origin=[{axis_origin.x:.3f},{axis_origin.y:.3f},{axis_origin.z:.3f}]  "
            f"dir=[{axis_dir.x:.4f},{axis_dir.y:.4f},{axis_dir.z:.4f}]"
        )
    else:
        # fallback: use XZ bbox diagonal direction
        axis_origin = target.Center()
        axis_dir = vnorm(cq.Vector(bb_t.xlen, 0.0, bb_t.zlen))
        print(
            "AXIS: fallback from bbox XZ spans  "
            f"origin=[{axis_origin.x:.3f},{axis_origin.y:.3f},{axis_origin.z:.3f}]  "
            f"dir=[{axis_dir.x:.4f},{axis_dir.y:.4f},{axis_dir.z:.4f}]"
        )

    # --- Broad faces: planar faces with normals ~ +/-Y (blade broad surfaces) ---
    broad_faces = []
    for fi, f in enumerate(t_faces):
        if f.geomType() != "PLANE":
            continue
        try:
            n = f.normalAt()
        except Exception:
            continue
        if abs(n.y) > 0.99:
            broad_faces.append((fi, f.Area(), f.Center(), n, f))

    print(f"SELECTED: {len(broad_faces)} planar broad-face candidates on s{copy_idx} (|normal.y|>0.99)")
    broad_faces.sort(key=lambda t: t[1], reverse=True)
    for k, (fi, a, c, n, _) in enumerate(broad_faces[:12]):
        print(
            f"  broad_face[{k}]: local_face_idx={fi} area={a:.3f} center=[{c.x:.3f},{c.y:.3f},{c.z:.3f}] normal=[{n.x:.3f},{n.y:.3f},{n.z:.3f}]"
        )

    if not broad_faces:
        print("ERROR: No broad faces found; returning input")
        return shape

    # Global edge index map (for printing indices)
    base_edges = base.Edges()
    edge_idx_by_hc = {}
    for ei, e in enumerate(base_edges):
        edge_idx_by_hc[hc(e)] = ei

    # Collect candidate edges from broad faces
    cand_edges = {}
    for _, _, _, _, f in broad_faces:
        for e in f.Edges():
            cand_edges[hc(e)] = e

    cand_list = list(cand_edges.values())
    print(f"SELECTED: {len(cand_list)} unique edges from broad faces on s{copy_idx}")

    # Filter to long, straight, axis-aligned edges near y-extremes (exclude central step), and compute distance-to-axis
    edge_info = []
    for e in cand_list:
        try:
            L = e.Length()
        except Exception:
            continue
        if L < 100.0:
            continue

        try:
            gt = e.geomType()
        except Exception:
            gt = "(unknown)"
        if gt != "LINE":
            continue

        vs = e.Vertices()
        if len(vs) < 2:
            continue
        p1 = vs[0].Center()
        p2 = vs[-1].Center()
        edir = vnorm(vsub(p2, p1))
        align = abs(vdot(edir, axis_dir))
        if align < 0.95:
            continue

        ce = e.Center()
        # Keep only edges on the main blade outer surfaces (y ~ 0 or 12.7), to avoid central crossing profile changes
        if not (abs(ce.y - 0.0) < 0.35 or abs(ce.y - 12.7) < 0.35):
            continue

        d_perp, t_along = dist_point_to_axis(ce, axis_origin, axis_dir)
        edge_info.append((d_perp, L, align, t_along, ce, e, gt))

    edge_info.sort(key=lambda t: (t[0], t[1]), reverse=True)
    print(f"SELECTED: {len(edge_info)} candidate long outer edges (LINE, L>100, aligned to blade axis, y~0/12.7) on s{copy_idx}")
    for k, (d_perp, L, align, t_along, ce, e, gt) in enumerate(edge_info[:20]):
        ei = edge_idx_by_hc.get(hc(e), None)
        print(
            f"  edge_cand[{k}]: global_edge_idx={ei} type={gt} L={L:.3f} align={align:.4f} d_perp={d_perp:.3f} t_along={t_along:.3f} center=[{ce.x:.3f},{ce.y:.3f},{ce.z:.3f}]"
        )

    if not edge_info:
        print("ERROR: No candidate edges found; returning input")
        return shape

    # Select the outermost distance band (includes split segments if the long edge is segmented by central features)
    max_d = edge_info[0][0]
    d_tol = 0.20
    selected = []
    sel_h = set()
    for d_perp, L, align, t_along, ce, e, gt in edge_info:
        if d_perp >= max_d - d_tol:
            h = hc(e)
            if h not in sel_h:
                sel_h.add(h)
                selected.append(e)

    sel_idx = [edge_idx_by_hc.get(hc(e), None) for e in selected]
    print(f"SELECTED: {len(selected)} edges for R1.27 fillet on s{copy_idx} (outermost band max_d={max_d:.3f}, tol={d_tol:.3f}) idx={sel_idx}")
    if len(selected) < 4:
        print("WARNING: Expected at least 4 long outer edges; selection is smaller than expected")

    # --- Apply fillet ---
    r = 1.27
    try:
        edited = target.fillet(r, selected)
        print(f"FILLET: succeeded on {len(selected)} edges with R={r:.3f} mm")
    except Exception as e:
        print(f"ERROR: Fillet failed on target blade s{copy_idx} with R={r:.3f}: {e}")
        return shape

    # --- Verification: find cylindrical faces of radius ~1.27 created by fillet and print achieved radius ---
    try:
        from OCP.BRepAdaptor import BRepAdaptor_Surface
        from OCP.GeomAbs import GeomAbs_Cylinder
    except Exception as e:
        print(f"WARNING: Could not import OCP adaptors for radius verification: {e}")
        BRepAdaptor_Surface = None
        GeomAbs_Cylinder = None

    cyl_rs = []
    cyl_faces = 0
    if BRepAdaptor_Surface is not None:
        for f in edited.Faces():
            if f.geomType() != "CYLINDER":
                continue
            try:
                ad = BRepAdaptor_Surface(f.wrapped, True)
                if GeomAbs_Cylinder is not None and ad.GetType() != GeomAbs_Cylinder:
                    continue
                rad = ad.Cylinder().Radius()
            except Exception:
                continue

            # Only consider likely long fillet cylinders (span along blade length)
            bb = f.BoundingBox()
            if max(bb.xlen, bb.zlen) < 80.0:
                continue

            cyl_faces += 1
            if abs(rad - r) < 0.05:
                cyl_rs.append(rad)

    print(f"VERIFY: found {cyl_faces} long cylindrical faces on edited blade s{copy_idx} (bbox long-dim>80mm)")
    print(f"VERIFY: found {len(cyl_rs)} long cylindrical faces with radius within ±0.05 of {r:.3f} mm")
    if cyl_rs:
        r_avg = sum(cyl_rs) / len(cyl_rs)
        r_min = min(cyl_rs)
        r_max = max(cyl_rs)
        print(f"ACHIEVED RADIUS: avg={r_avg:.4f}  min={r_min:.4f}  max={r_max:.4f}  (target {r:.3f})")
    else:
        print("WARNING: Could not confirm R1.27 numerically; rely on render inspection")

    # --- Recompound with only the target blade replaced; other bodies untouched ---
    out_solids = []
    for i, s in enumerate(solids):
        out_solids.append(edited if i == copy_idx else s)
    out = cq.Compound.makeCompound(out_solids)
    return out

